import { describe, it, expect } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [1000, "US"],
    [0, "FR"],
    [-500, "GB"],
  ])("returns 0 for taxable=%i, region=%s", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it.each([
      [-0.01, "defaultRate must be between 0 and 1"],
      [1.01, "defaultRate must be between 0 and 1"],
      [NaN, "defaultRate must be between 0 and 1"],
      [Infinity, "defaultRate must be between 0 and 1"],
    ])("rejects invalid defaultRate %s", (rate, msg) => {
      expect(() => new RegionalTaxCalculator({}, rate)).toThrow(RangeError);
      expect(() => new RegionalTaxCalculator({}, rate)).toThrow(msg);
    });

    it("rejects invalid region rate", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": 1.5 }),
      ).toThrow("rate for US must be between 0 and 1");
    });

    it("rejects negative region rate", () => {
      expect(
        () => new RegionalTaxCalculator({ "FR": -0.1 }),
      ).toThrow("rate for FR must be between 0 and 1");
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US": 0.08, "US-CA": 0.0875, "FR": 0.2 },
      0.05,
    );

    it.each([
      [1000, "US", 80],         // 8% of 1000
      [1000, "US-CA", 87],      // 8.75% of 1000 = 87.5 → 87
      [1000, "FR", 200],        // 20% of 1000
      [1000, "JP", 50],         // unknown → default 5%
      [0, "US", 0],             // zero taxable
      [-100, "US", 0],          // negative taxable
    ])(
      "tax on %i cents in %s = %i",
      (taxable, region, expected) => {
        expect(calc.computeTaxCents(taxable, region)).toBe(expected);
      },
    );

    it("rounds down fractional cents", () => {
      // 8.75% of 999 = 87.4125 → 87
      expect(calc.computeTaxCents(999, "US-CA")).toBe(87);
    });

    it("uses default rate 0 when not specified", () => {
      const calc0 = new RegionalTaxCalculator({});
      expect(calc0.computeTaxCents(1000, "XX")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax from async provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.1,
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(1000, "US")).toBe(100);
  });

  it("floors fractional results", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.0875,
    };
    const calc = new AsyncTaxCalculator(provider);
    // 8.75% of 999 = 87.4125 → 87
    expect(await calc.computeTaxCents(999, "US")).toBe(87);
  });

  it("returns 0 for zero taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.1,
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.1,
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
  });

  it("throws on invalid rate from provider (> 1)", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 1.5,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws on negative rate from provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => -0.1,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(
      "tax rate for US must be between 0 and 1",
    );
  });

  it("throws on NaN rate from provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => NaN,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => { throw new Error("service down"); },
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow("service down");
  });
});

describe("totalLineWeightGrams", () => {
  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 500 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 200, weightGrams: 300 }, quantity: 3 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(1900); // 500*2 + 300*3
  });

  it("treats undefined weight as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

