+  describe("computeShippingCents", () => {
+    const calc = new WeightBasedShippingCalculator([
+      { upToGrams: 500, costCents: 300 },
+      { upToGrams: 1000, costCents: 500 },
+      { upToGrams: 5000, costCents: 800 },
+    ]);
+
+    it("returns 0 for empty cart", () => {
+      expect(calc.computeShippingCents([], 0)).toBe(0);
+    });
+
+    it("returns 0 when total weight is 0", () => {
+      // product has no weightGrams
+      expect(calc.computeShippingCents([line("a", 100, 1)], 100)).toBe(0);
+    });
+
+    it("selects first bracket at exact boundary", () => {
+      // 500g exactly → first bracket
+      expect(
+        calc.computeShippingCents([line("a", 100, 1, 500)], 100),
+      ).toBe(300);
+    });
+
+    it("selects first bracket for weight below boundary", () => {
+      expect(
+        calc.computeShippingCents([line("a", 100, 1, 499)], 100),
+      ).toBe(300);
+    });
+
+    it("selects second bracket when weight exceeds first", () => {
+      // 501g → second bracket (up to 1000g)
+      expect(
+        calc.computeShippingCents([line("a", 100, 1, 501)], 100),
+      ).toBe(500);
+    });
+
+    it("selects correct bracket with multiple items", () => {
+      // 2 items of 300g = 600g → second bracket
+      expect(
+        calc.computeShippingCents([line("a", 100, 2, 300)], 200),
+      ).toBe(500);
+    });
+
+    it("uses overflow cost when weight exceeds all brackets", () => {
+      const calcWithOverflow = new WeightBasedShippingCalculator(
+        [
+          { upToGrams: 500, costCents: 300 },
+          { upToGrams: 1000, costCents: 500 },
+        ],
+        1200,
+      );
+      // 1500g exceeds all brackets → overflow
+      expect(
+        calcWithOverflow.computeShippingCents([line("a", 100, 1, 1500)], 100),
+      ).toBe(1200);
+    });
+
+    it("falls back to last bracket cost when no overflow specified", () => {
+      // 6000g exceeds all brackets, no overflow → last bracket cost (800)
+      expect(
+        calc.computeShippingCents([line("a", 100, 1, 6000)], 100),
+      ).toBe(800);
+    });
+
+    it("sorts brackets regardless of input order", () => {
+      const unsorted = new WeightBasedShippingCalculator([
+        { upToGrams: 1000, costCents: 500 },
+        { upToGrams: 500, costCents: 300 },
+      ]);
+      // 400g should hit the 500g bracket (300 cents)
+      expect(
+        unsorted.computeShippingCents([line("a", 100, 1, 400)], 100),
+      ).toBe(300);
+    });
+  });
+});
