+      const cart = new Cart();
+      cart.add(product("a", 500), 2);
+      expect(cart.itemCount).toBe(2);
+    });
+
+    it("merges quantities when adding same product", () => {
+      const cart = new Cart();
+      cart.add(product("a", 500), 2);
+      cart.add(product("a", 500), 3);
+      expect(cart.itemCount).toBe(5);
+    });
+
+    it("rejects non-positive quantity", () => {
+      const cart = new Cart();
+      expect(() => cart.add(product("a", 500), 0)).toThrow(RangeError);
+      expect(() => cart.add(product("a", 500), -1)).toThrow(RangeError);
+    });
+
+    it("rejects non-integer quantity", () => {
+      const cart = new Cart();
+      expect(() => cart.add(product("a", 500), 1.5)).toThrow(RangeError);
+    });
+
+    it("rejects negative unit price", () => {
+      const cart = new Cart();
+      expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
+    });
+  });
+
+  describe("remove", () => {
+    it("removes an existing product and returns true", () => {
+      const cart = new Cart();
+      cart.add(product("a", 500), 1);
+      expect(cart.remove("a")).toBe(true);
+      expect(cart.itemCount).toBe(0);
+    });
+
+    it("returns false for unknown product", () => {
+      const cart = new Cart();
+      expect(cart.remove("nonexistent")).toBe(false);
+    });
+  });
+
+  describe("updateQuantity", () => {
+    it("updates quantity of existing product", () => {
+      const cart = new Cart();
+      cart.add(product("a", 500), 2);
+      cart.updateQuantity("a", 5);
+      expect(cart.itemCount).toBe(5);
+    });
+
+    it("removes product when quantity is set to 0", () => {
+      const cart = new Cart();
+      cart.add(product("a", 500), 2);
+      cart.updateQuantity("a", 0);
+      expect(cart.itemCount).toBe(0);
+      expect(cart.remove("a")).toBe(false); // already gone
+    });
+
+    it("throws for unknown product", () => {
+      const cart = new Cart();
+      expect(() => cart.updateQuantity("x", 1)).toThrow("not in the cart");
+    });
+
+    it("rejects negative quantity", () => {
+      const cart = new Cart();
+      cart.add(product("a", 500), 1);
+      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
+    });
+
+    it("rejects non-integer quantity", () => {
+      const cart = new Cart();
+      cart.add(product("a", 500), 1);
+      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
+    });
+  });
+
+  describe("clear", () => {
+    it("empties the cart", () => {
+      const cart = new Cart();
+      cart.add(product("a", 500), 2);
+      cart.add(product("b", 300), 1);
+      cart.clear();
+      expect(cart.itemCount).toBe(0);
+    });
+  });
+
+  describe("snapshot", () => {
+    it("returns deep copy of lines", () => {
+      const cart = new Cart();
+      const p = product("a", 500);
+      cart.add(p, 2);
+      const snap = cart.snapshot();
+      expect(snap).toHaveLength(1);
+      expect(snap[0]!.product.id).toBe("a");
+      expect(snap[0]!.quantity).toBe(2);
+
+      // mutating snapshot does not affect cart
+      (snap[0] as { quantity: number }).quantity = 99;
+      expect(cart.itemCount).toBe(2);
+    });
+  });
+
+  describe("totals — pricing pipeline", () => {
+    it("computes subtotal as sum of price * quantity", () => {
+      const cart = new Cart();
+      cart.add(product("a", 500), 2);
+      cart.add(product("b", 300), 3);
+      const totals = cart.totals();
+      expect(totals.subtotalCents).toBe(1900); // 1000 + 900
+    });
+
+    it("returns all zeros for empty cart", () => {
+      const cart = new Cart();
+      const totals = cart.totals();
+      expect(totals).toEqual({
+        subtotalCents: 0,
+        discountCents: 0,
+        taxCents: 0,
+        shippingCents: 0,
+        totalCents: 0,
+      });
+    });
+
+    it("applies discount then tax on discounted subtotal", () => {
+      const discount: DiscountPolicy = {
+        computeDiscountCents: vi.fn().mockReturnValue(200),
+      };
+      const tax: TaxCalculator = {
+        computeTaxCents: vi.fn().mockReturnValue(80),
+      };
+      const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
+      cart.add(product("a", 1000), 1);
+      const totals = cart.totals();
+
+      expect(totals.subtotalCents).toBe(1000);
+      expect(totals.discountCents).toBe(200);
+      // tax should be computed on discounted subtotal (800)
+      expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
+      expect(totals.taxCents).toBe(80);
+      expect(totals.totalCents).toBe(800 + 80); // discounted + tax + shipping(0)
+    });
+
+    it("clamps discount to [0, subtotal]", () => {
+      const overDiscount: DiscountPolicy = {
+        computeDiscountCents: vi.fn().mockReturnValue(5000),
+      };
+      const cart = new Cart({ discountPolicy: overDiscount });
+      cart.add(product("a", 1000), 1);
+      const totals = cart.totals();
+      expect(totals.discountCents).toBe(1000); // clamped to subtotal
+      expect(totals.totalCents).toBe(0);
+    });
+
+    it("clamps negative discount to 0", () => {
+      const negDiscount: DiscountPolicy = {
+        computeDiscountCents: vi.fn().mockReturnValue(-100),
+      };
+      const cart = new Cart({ discountPolicy: negDiscount });
+      cart.add(product("a", 1000), 1);
+      expect(cart.totals().discountCents).toBe(0);
+    });
+
+    it("clamps negative tax to 0", () => {
+      const tax: TaxCalculator = {
+        computeTaxCents: vi.fn().mockReturnValue(-50),
+      };
+      const cart = new Cart({ taxCalculator: tax });
+      cart.add(product("a", 1000), 1);
+      expect(cart.totals().taxCents).toBe(0);
+    });
+
+    it("clamps negative shipping to 0", () => {
+      const shipping: ShippingCalculator = {
+        computeShippingCents: vi.fn().mockReturnValue(-100),
+      };
+      const cart = new Cart({ shippingCalculator: shipping });
+      cart.add(product("a", 1000), 1);
+      expect(cart.totals().shippingCents).toBe(0);
+    });
+
+    it("passes lines and discounted subtotal to shipping calculator", () => {
+      const discount: DiscountPolicy = {
+        computeDiscountCents: vi.fn().mockReturnValue(200),
+      };
+      const shipping: ShippingCalculator = {
+        computeShippingCents: vi.fn().mockReturnValue(500),
+      };
+      const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
+      cart.add(product("a", 1000), 1);
+      cart.totals();
+
+      // shipping sees discounted subtotal (800)
+      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
+        expect.any(Array),
+        800,
+      );
+    });
+
+    it("uses default region 'US'", () => {
+      const tax: TaxCalculator = {
+        computeTaxCents: vi.fn().mockReturnValue(0),
+      };
+      const cart = new Cart({ taxCalculator: tax });
+      cart.add(product("a", 1000), 1);
+      cart.totals();
+      expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
+    });
+
+    it("uses custom region", () => {
+      const tax: TaxCalculator = {
+        computeTaxCents: vi.fn().mockReturnValue(0),
+      };
+      const cart = new Cart({ taxCalculator: tax, region: "FR" });
+      cart.add(product("a", 1000), 1);
+      cart.totals();
+      expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
+    });
+
+    it("computes full pipeline: subtotal → discount → tax → shipping", () => {
+      const discount: DiscountPolicy = {
+        computeDiscountCents: () => 500,
+      };
+      const tax: TaxCalculator = {
+        computeTaxCents: (taxable) => Math.floor(taxable * 0.1),
+      };
+      const shipping: ShippingCalculator = {
+        computeShippingCents: () => 599,
+      };
+      const cart = new Cart({
+        discountPolicy: discount,
+        taxCalculator: tax,
+        shippingCalculator: shipping,
+      });
+      cart.add(product("a", 2000), 1);
+      cart.add(product("b", 1000), 3);
+      // subtotal = 2000 + 3000 = 5000
+      // discount = 500
+      // discounted = 4500
+      // tax = 450
+      // shipping = 599
+      // total = 4500 + 450 + 599 = 5549
+      const totals = cart.totals();
+      expect(totals.subtotalCents).toBe(5000);
+      expect(totals.discountCents).toBe(500);
+      expect(totals.taxCents).toBe(450);
+      expect(totals.shippingCents).toBe(599);
+      expect(totals.totalCents).toBe(5549);
+    });
+  });
+
+  describe("checkout", () => {
+    let cart: Cart;
+
+    beforeEach(() => {
+      cart = new Cart();
+      cart.add(product("p1", 1000), 2);
+      cart.add(product("p2", 500), 1);
+    });
+
+    it("returns totals and lines without collaborators", async () => {
+      const result = await cart.checkout();
+      expect(result.totals.subtotalCents).toBe(2500);
+      expect(result.lines).toHaveLength(2);
+    });
+
+    it("refreshes prices via priceFetcher", async () => {
+      const priceFetcher: PriceFetcher = {
+        fetchPriceCents: vi.fn()
+          .mockResolvedValueOnce(1200) // p1: 1000 → 1200
+          .mockResolvedValueOnce(600),  // p2: 500 → 600
+      };
+      const result = await cart.checkout({ priceFetcher });
+      // refreshed subtotal: 1200*2 + 600*1 = 3000
+      expect(result.totals.subtotalCents).toBe(3000);
+      expect(result.lines[0]!.product.unitPriceCents).toBe(1200);
+      expect(result.lines[1]!.product.unitPriceCents).toBe(600);
+    });
+
+    it("checks inventory and passes when all available", async () => {
+      const inventoryChecker: InventoryChecker = {
+        check: vi.fn().mockResolvedValue({ available: true }),
+      };
+      const result = await cart.checkout({ inventoryChecker });
+      expect(result.totals.subtotalCents).toBe(2500);
+      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
+    });
+
+    it("throws InventoryError when item is unavailable", async () => {
+      const inventoryChecker: InventoryChecker = {
+        check: vi.fn().mockResolvedValue({
+          available: false,
+          reason: "out of stock",
+        }),
+      };
+
+      try {
+        await cart.checkout({ inventoryChecker });
+        expect.fail("should have thrown");
+      } catch (err) {
+        expect(err).toBeInstanceOf(InventoryError);
+        const invErr = err as InventoryError;
+        expect(invErr.productId).toBe("p1");
+        expect(invErr.requested).toBe(2);
+        expect(invErr.message).toBe("out of stock");
+      }
+    });
+
+    it("throws InventoryError on partial stock denial", async () => {
+      const inventoryChecker: InventoryChecker = {
+        check: vi.fn().mockResolvedValue({
+          available: true,
+          availableQuantity: 1, // less than requested 2
+        }),
+      };
+
+      try {
+        await cart.checkout({ inventoryChecker });
+        expect.fail("should have thrown");
+      } catch (err) {
+        expect(err).toBeInstanceOf(InventoryError);
+        const invErr = err as InventoryError;
+        expect(invErr.available).toBe(1);
+        expect(invErr.requested).toBe(2);
+      }
+    });
+
+    it("uses asyncTaxProvider for tax computation", async () => {
+      const asyncTaxProvider: AsyncTaxRateProvider = {
+        getRate: vi.fn().mockResolvedValue(0.1),
+      };
+      const result = await cart.checkout({ asyncTaxProvider });
+      // subtotal 2500, no discount → tax = floor(2500 * 0.1) = 250
+      expect(result.totals.taxCents).toBe(250);
+      expect(result.totals.totalCents).toBe(2750);
+    });
+
+    it("combines priceFetcher + asyncTaxProvider + discount", async () => {
+      const discount: DiscountPolicy = {
+        computeDiscountCents: () => 500,
+      };
+      const shipping: ShippingCalculator = {
+        computeShippingCents: () => 300,
+      };
+      const cartWithPolicies = new Cart({
+        discountPolicy: discount,
+        shippingCalculator: shipping,
+      });
+      cartWithPolicies.add(product("p1", 1000), 2);
+
+      const priceFetcher: PriceFetcher = {
+        fetchPriceCents: vi.fn().mockResolvedValue(1500),
+      };
+      const asyncTaxProvider: AsyncTaxRateProvider = {
+        getRate: vi.fn().mockResolvedValue(0.08),
+      };
+
+      const result = await cartWithPolicies.checkout({
+        priceFetcher,
+        asyncTaxProvider,
+      });
+      // subtotal: 1500*2 = 3000
+      // discount: 500
+      // discounted: 2500
+      // tax: floor(2500 * 0.08) = 200
+      // shipping: 300
+      // total: 2500 + 200 + 300 = 3000
+      expect(result.totals.subtotalCents).toBe(3000);
+      expect(result.totals.discountCents).toBe(500);
+      expect(result.totals.taxCents).toBe(200);
+      expect(result.totals.shippingCents).toBe(300);
+      expect(result.totals.totalCents).toBe(3000);
+    });
+
+    it("propagates priceFetcher rejection", async () => {
+      const priceFetcher: PriceFetcher = {
+        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
+      };
+      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("fetch failed");
+    });
+
+    it("propagates asyncTaxProvider rejection", async () => {
+      const asyncTaxProvider: AsyncTaxRateProvider = {
+        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
+      };
+      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
+        "tax service down",
+      );
+    });
+
+    it("runs inventory check after price refresh", async () => {
+      const callOrder: string[] = [];
+      const priceFetcher: PriceFetcher = {
+        fetchPriceCents: vi.fn().mockImplementation(async () => {
+          callOrder.push("price");
+          return 1000;
+        }),
+      };
+      const inventoryChecker: InventoryChecker = {
+        check: vi.fn().mockImplementation(async () => {
+          callOrder.push("inventory");
+          return { available: true } as InventoryDecision;
+        }),
+      };
+      await cart.checkout({ priceFetcher, inventoryChecker });
+      // all price fetches should happen before inventory checks
+      const priceIndices = callOrder
+        .map((c, i) => (c === "price" ? i : -1))
+        .filter((i) => i >= 0);
+      const inventoryIndices = callOrder
+        .map((c, i) => (c === "inventory" ? i : -1))
+        .filter((i) => i >= 0);
+      expect(Math.max(...priceIndices)).toBeLessThan(
+        Math.min(...inventoryIndices),
+      );
+    });
+
+    it("checkout on empty cart returns zero totals", async () => {
+      const emptyCart = new Cart();
+      const result = await emptyCart.checkout();
+      expect(result.totals.totalCents).toBe(0);
+      expect(result.lines).toHaveLength(0);
+    });
+  });
+});
